PAGE = r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>学习规则审核</title><style>body{font:16px system-ui;margin:32px;background:#f5f5f7;color:#222}main{max-width:1200px;margin:auto}article{background:white;padding:24px;margin:20px 0;border-radius:16px}pre{white-space:pre-wrap;overflow-wrap:anywhere}button,a{margin-right:12px}button{padding:10px 18px;cursor:pointer}.error{color:#a22}</style><main><a href="/">返回工作台</a><h1>学习规则审核</h1><p>模型梳理规则，程序限定范围。复杂规则批准后仅辅助判断；不能覆盖 Excel、人工纠正、真实候选或保存校验。</p><p>停用后停止复用。新人工证据使已批准规则发生变化时，自动暂停并重新评估。</p><p id="status" role="status"></p><div id="rules"></div></main><script>
const labels={active:'自动规则 · 已通过验证',pending_review:'待审核',approved_guidance:'已批准 · 判断参考',suspended:'已暂停',disabled:'已停用'};
async function load(){try{const response=await fetch('/api/model-rules');if(!response.ok)throw Error('请先登录工作台');const data=await response.json();const root=document.getElementById('rules');root.replaceChildren();for(const r of data.rules){const card=document.createElement('article');const title=document.createElement('h2');title.textContent=(r.scope.platform_id+' · '+r.scope.field_label+' · '+labels[r.status]);card.append(title);const detail=document.createElement('pre');detail.textContent='适用范围：'+JSON.stringify(r.scope,null,2)+'\n模型建议：'+JSON.stringify(r.proposal,null,2)+'\n验证结果：'+JSON.stringify(r.validation,null,2)+'\n人工证据：'+JSON.stringify(r.evidence,null,2)+'\n版本：'+r.id;card.append(detail);for(const [action,label] of (r.status==='pending_review'?[['approve','同意，作为判断参考'],['disable','不采用']]:['active','approved_guidance'].includes(r.status)?[['disable','停用规则']]:[])){const b=document.createElement('button');b.textContent=label;b.onclick=async()=>{b.disabled=true;try{const res=await fetch('/api/model-rules/'+r.id+'/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({updated_at:r.updated_at})});if(!res.ok)throw Error('操作失败或记录已更新，请刷新后重试');await load();}catch(e){document.getElementById('status').textContent=e.message;b.disabled=false;}};card.append(b);}root.append(card);}if(!data.rules.length)root.textContent='暂无模型提出的学习规则。遇到需要模型判断的字段时，会结合历史经验逐步梳理。';}catch(e){document.getElementById('status').textContent=e.message;}}load();
</script></html>'''
